import { writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";

import openapiTS, { astToString } from "openapi-typescript";

const DEFAULT_API_URL = "http://localhost:3000";
const OUT_FILE = "src/shared/api/generated/schema.d.ts";
const HEADER = `/**
 * This file was auto-generated by openapi-typescript.
 * Do not make direct changes to the file.
 */

`;

type Source = Parameters<typeof openapiTS>[0];

// The file is written only after the types are generated, so an unreachable
// backend or an invalid document never touches the committed types.
export async function generateApiTypes(
  source: Source,
  outFile: string,
): Promise<void> {
  const types = astToString(await openapiTS(source));

  await writeFile(outFile, `${HEADER}${types}`);
}

const isEntryPoint = process.argv[1] === fileURLToPath(import.meta.url);

if (isEntryPoint) {
  const baseUrl = (process.env.API_URL || DEFAULT_API_URL).replace(/\/+$/, "");

  try {
    await generateApiTypes(new URL(`${baseUrl}/docs-json`), OUT_FILE);
  } catch (error) {
    console.error(
      `Cannot generate API types from ${baseUrl}/docs-json: ${
        error instanceof Error ? error.message : error
      }`,
    );
    process.exit(1);
  }
}
